20	const SKIP = new RegExp(
21	  "adjustment|appeals|BZA|architectur|historic|landmark|park|library|police|fire|pension|retire|" +
22	    "tif|tax increment|equalization|merit|ethics|youth|senior|arts|tree|beautif|cemetery|" +
23	    "traffic|personnel|audit|finance|budget|work ?session|special|port authority|road board|" +
24	    "committee|advisory|task force|group|steering|notices|emergency", "i");
25	const PZ = /planning|zoning|P\s*&\s*Z|plan commission/i;
26	const GOV = /aldermen|alderm|city council|county council|board of trustees|village board|^council$|\bcouncil\b(?!.*(advisory|youth|arts))/i;
27	const NOT_HEARING = /work ?session|study session|retreat|orientation|training|closed session|executive session/i;
28	// ...unless it's combined with the regular meeting ("Work Session and Council Meeting").
29	const REGULAR = /regular|(council|board|commission|aldermen) meeting/i;
30	// Postings that aren't a meeting at all ("No regular meeting to be held", "Notice of Public Hearing - Proposed Budget").
31	const NOT_MEETING = /no (regular )?meeting|^notice of/i;
32	const notHearing = (title: string) => NOT_MEETING.test(title) || (NOT_HEARING.test(title) && !REGULAR.test(title));
33	const CANCELLED = /cancell?ed/i;
34	
35	type Body = "planning_zoning" | "governing_body";
36	type Collected = {
37	  body: Body; event_date: string; event_time: string | null; location: string | null; title: string;
38	  agenda_url: string | null; packet_url: string | null; minutes_url: string | null; source_url: string; cancelled: boolean;
39	};
40	
41	// One row per board and date. A cancelled posting gives way to a live one on the same date
42	// (a cancelled special session alongside the regular meeting). Minutes may sit on another row for the same date.
43	function keep(rows: Map<string, Collected>, c: Collected) {
44	  const key = `${c.body}|${c.event_date}`;
45	  const prev = rows.get(key);
46	  if (!prev || (prev.cancelled && !c.cancelled)) rows.set(key, { ...c, minutes_url: c.minutes_url ?? prev?.minutes_url ?? null });
47	  else if (!prev.minutes_url && c.minutes_url) prev.minutes_url = c.minutes_url;
48	}
49	
50	function bodyFor(name: string): Body | null {
51	  if (SKIP.test(name)) return null;
52	  if (PZ.test(name)) return "planning_zoning";
53	  if (GOV.test(name)) return "governing_body";
54	  return null;
55	}
