57	async function fetchText(url: string, form?: Record<string, string | number>) {
58	  const res = await fetch(url, {
59	    method: form ? "POST" : "GET",
60	    headers: form ? { ...UA, "Content-Type": "application/x-www-form-urlencoded" } : UA,
61	    body: form ? new URLSearchParams(Object.entries(form).map(([k, v]) => [k, String(v)])) : undefined,
62	    redirect: "follow",
63	  });
64	  const text = await res.text();
65	  if (/Attention Required! \| Cloudflare|cf-error-details|Just a moment\.\.\./.test(text)) throw new Error(`blocked by bot protection: ${url}`);
66	  if (!res.ok) throw new Error(`HTTP ${res.status}: ${url}`);
67	  return { url: res.url, text };
68	}
69	
70	const unescape = (s: string) =>
71	  s.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
72	
73	// ---- CivicPlus AgendaCenter: only meetings whose agenda has been posted.
74	async function agendaCenter(site: string, year: number): Promise<Collected[]> {
75	  const { url, text: page } = await fetchText(site.replace(/\/$/, "") + "/AgendaCenter");
76	  const base = new URL(url).origin;
77	  const rows = new Map<string, Collected>();
78	  // Boards are <h2> headings, or <h3> on sites that group boards under section headings (Des Peres).
79	  for (const m of page.matchAll(/id="cat(\d+)">\s*<h[23][^>]*>([^<]+)<\/h[23]>/g)) {
80	    const [, cid, rawName] = m;
81	    const name = unescape(rawName).trim();
82	    const body = bodyFor(name);
83	    const years = [...page.matchAll(new RegExp(`changeYear\\((\\d{4}), ${cid}\\b`, "g"))].map((y) => Number(y[1]));
84	    if (!body || Math.max(0, ...years) < year) continue;
85	    const { text: part } = await fetchText(base + "/AgendaCenter/UpdateCategoryList", { year, catID: cid });
86	    for (const r of part.matchAll(/<tr id="row\w+" class="catAgendaRow">([\s\S]*?)<\/tr>/g)) {
87	      const row = r[1];
88	      const a = row.match(/name="_(\d{2})(\d{2})(\d{4})-(\d+)"/);
89	      if (!a) continue;
90	      const [, mm, dd, yyyy, id] = a;
91	      const t = row.match(/aria-describedby="h4[^"]*">\s*([\s\S]*?)\s*<\/a>/);
92	      const title = t ? unescape(t[1].replace(/\s+/g, " ")).trim() : "";
93	      if (notHearing(title)) continue;
94	      const agendaUrl = `${base}/AgendaCenter/ViewFile/Agenda/_${mm}${dd}${yyyy}-${id}`;
95	      // Agendas built in AgendaCenter also offer the compiled packet (agenda plus staff reports and plans).
96	      const packet = row.includes(`_${mm}${dd}${yyyy}-${id}?packet=true`) ? `${agendaUrl}?packet=true` : null;
97	      const minutes = row.match(/href="(\/AgendaCenter\/ViewFile\/Minutes\/[^"]+)"/);
98	      keep(rows, {
99	        body, event_date: `${yyyy}-${mm}-${dd}`, event_time: null, location: null, title, agenda_url: agendaUrl,
100	        packet_url: packet, minutes_url: minutes ? base + unescape(minutes[1]) : null, source_url: `${base}/AgendaCenter`, cancelled: CANCELLED.test(title),
101	      });
102	    }
103	  }
104	  return [...rows.values()];
105	}
