107	// ---- CivicClerk: public OData API, includes scheduled future meetings. Times are local despite the "Z".
108	async function civicClerk(tenant: string, year: number): Promise<Collected[]> {
109	  const api = (path: string, q: Record<string, string | number> = {}) =>
110	    `https://${tenant}.api.civicclerk.com/v1/${path}?` + Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(String(v))}`).join("&");
111	  const flt = `startDateTime ge ${year}-01-01T00:00:00Z and startDateTime lt ${year + 1}-01-01T00:00:00Z`;
112	  // deno-lint-ignore no-explicit-any
113	  const events: any[] = [];
114	  for (;;) { // 15 per page whatever $top says
115	    const { text } = await fetchText(api("Events", { $filter: flt, $orderby: "startDateTime", $skip: events.length }));
116	    const page = JSON.parse(text).value ?? [];
117	    if (!page.length) break;
118	    events.push(...page);
119	    if (events.length > 2000) break;
120	  }
121	  const rows = new Map<string, Collected>();
122	  for (const e of events) {
123	    const body = bodyFor(e.categoryName ?? e.eventCategoryName ?? "");
124	    if (!body || notHearing(e.eventName) || e.isDeleted) continue;
125	    const local: string = e.startDateTime.slice(0, 16);
126	    // deno-lint-ignore no-explicit-any
127	    const file = (type: string) => (e.publishedFiles ?? []).find((f: any) => f.type === type);
128	    const fileUrl = (f: { fileId: number } | undefined) =>
129	      f ? api(`Meetings/GetMeetingFileStream(fileId=${f.fileId},plainText=false)`).replace(/\?$/, "") : null;
130	    const loc = e.eventLocation ?? {};
131	    const time = local.slice(11, 16);
132	    keep(rows, {
133	      body, event_date: local.slice(0, 10), event_time: time && time !== "00:00" ? time : null,
134	      location: [loc.address1, loc.address2].filter(Boolean).join(", ") || null,
135	      title: e.eventName,
136	      agenda_url: fileUrl(file("Agenda")), packet_url: fileUrl(file("Agenda Packet")), minutes_url: fileUrl(file("Minutes")),
137	      source_url: `https://${tenant}.portal.civicclerk.com/event/${e.id}/files`, cancelled: CANCELLED.test(e.eventName),
138	    });
139	  }
140	  return [...rows.values()];
141	}
