188	Deno.serve(async (req) => {
189	  const url = new URL(req.url);
190	  const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
191	  const { data: tok } = await db.from("app_settings").select("value").eq("key", "digest_token").single();
192	  if (!tok || req.headers.get("x-digest-token") !== tok.value) return new Response("Not found", { status: 404 });
193	
194	  const today = new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date());
195	  const year = Number(today.slice(0, 4));
196	  // Late in the year, also pick up next year's meetings as cities post them. ?years=2021,2022 backfills past years
197	  // (one jurisdiction and year per call keeps CivicClerk's 15-per-page paging under the time limit).
198	  const asked = (url.searchParams.get("years") ?? "").split(",").map(Number).filter((y) => y >= 2000 && y <= year + 1);
199	  const years = asked.length ? asked.sort((a, b) => a - b) : Number(today.slice(5, 7)) >= 11 ? [year, year + 1] : [year];
200	
201	  let q = db.from("jurisdictions").select("id, collector, collector_ref").not("collector", "is", null);
202	  const only = url.searchParams.get("j");
203	  q = only ? q.eq("id", only) : q.eq("followed", true);
204	  const { data: js, error } = await q;
205	  if (error) return new Response(error.message, { status: 500 });
206	
207	  const runOne = async (j: { id: string; collector: string; collector_ref: string }) => {
208	    const fullSchedule = j.collector !== "agendacenter";
209	    try {
210	      const collected: Collected[] = [];
211	      for (const y of years) {
212	        collected.push(...await COLLECTORS[j.collector](j.collector_ref, y));
213	      }
214	      const { data: existing } = await db.from("meetings")
215	        .select("id, body, event_date, event_time, location, agenda_url, packet_url, minutes_url, status")
216	        .eq("jurisdiction_id", j.id).eq("event_type", "meeting")
217	        .gte("event_date", `${years[0]}-01-01`).lte("event_date", `${years[years.length - 1]}-12-31`);
218	      const have = new Map((existing ?? []).map((m) => [`${m.body}|${m.event_date}`, m]));
219	      const seen = new Set(collected.map((c) => `${c.body}|${c.event_date}`));
220	
221	      const inserts = [];
222	      let updated = 0;
223	      for (const c of collected) {
224	        const m = have.get(`${c.body}|${c.event_date}`);
225	        if (!m) {
226	          inserts.push({
227	            jurisdiction_id: j.id, body: c.body, event_type: "meeting", event_date: c.event_date, event_time: c.event_time,
228	            location: c.location, status: c.cancelled ? "cancelled" : "published", source_url: c.source_url,
229	            agenda_url: c.agenda_url, packet_url: c.packet_url, minutes_url: c.minutes_url, verified_on: today,
230	            note: /special/i.test(c.title) ? "Special meeting" : null,
231	          });
232	          continue;
233	        }
234	        const patch: Record<string, unknown> = {};
235	        if (!m.agenda_url && c.agenda_url) patch.agenda_url = c.agenda_url;
236	        // A different agenda link for an upcoming meeting is usually an amended agenda; extract-agendas' recheck
237	        // sees the new file and reads it again.
238	        else if (m.agenda_url && c.agenda_url && c.agenda_url !== m.agenda_url && c.event_date >= today) patch.agenda_url = c.agenda_url;
239	        if (!m.packet_url && c.packet_url) patch.packet_url = c.packet_url;
240	        if (!m.minutes_url && c.minutes_url) patch.minutes_url = c.minutes_url;
241	        if (!m.event_time && c.event_time) patch.event_time = c.event_time;
242	        if (!m.location && c.location) patch.location = c.location;
243	        if (m.status === "projected" && c.cancelled) patch.status = "cancelled";
244	        else if (m.status === "projected" && (c.agenda_url || fullSchedule)) patch.status = "published";
245	        if (Object.keys(patch).length) {
246	          patch.verified_on = today;
247	          const { error: ue } = await db.from("meetings").update(patch).eq("id", m.id);
248	          if (ue) throw new Error(ue.message);
249	          updated++;
250	        }
251	      }
252	      if (inserts.length) {
253	        const { error: ie } = await db.from("meetings").insert(inserts);
254	        if (ie) throw new Error(ie.message);
255	      }
256	      // CivicClerk and Municode list the whole schedule, so anything they lack is suspect. AgendaCenter only
257	      // lists posted agendas, so only past meetings (a few days' grace) count there.
258	      const cutoff = fullSchedule ? "9999-12-31" : new Date(Date.now() - 3 * 864e5).toISOString().slice(0, 10);
259	      const missing = collected.length
260	        ? (existing ?? []).filter((m) => m.status !== "cancelled" && m.event_date <= cutoff && !seen.has(`${m.body}|${m.event_date}`))
261	          .map((m) => ({ event_date: m.event_date, body: m.body }))
262	        : [];
263	      await db.from("jurisdictions").update({ collected_on: new Date().toISOString() }).eq("id", j.id);
264	      const run = { jurisdiction_id: j.id, ok: true, found: collected.length, inserted: inserts.length, updated, missing: missing.length ? missing : null };
265	      await db.from("collector_runs").insert(run);
266	      return run;
267	    } catch (e) {
268	      const run = { jurisdiction_id: j.id, ok: false, error: String((e as Error).message ?? e).slice(0, 500) };
269	      await db.from("collector_runs").insert(run);
270	      return run;
271	    }
272	  };
273	
274	  // A few sites at a time, to stay polite to small-town web servers.
275	  const results: unknown[] = [];
276	  const queue = [...(js ?? [])];
277	  await Promise.all(Array.from({ length: 6 }, async () => {
278	    for (let j = queue.shift(); j; j = queue.shift()) results.push(await runOne(j));
279	  }));
280	  return new Response(JSON.stringify(results, null, 1), { headers: { "Content-Type": "application/json" } });
281	});
