1	// Live iCalendar feed of meetings and submittal deadlines.
2	// Subscribe in Google Calendar / Outlook by URL so it appears as its own calendar:
3	//   https://<project>.supabase.co/functions/v1/calendar?token=<CALENDAR_TOKEN>
4	// Optional: &j=wentzville,cottleville to limit to certain jurisdictions.
5	// Deployed with verify_jwt off (calendar apps can't send a JWT); the token guards access.
6	import { createClient } from "jsr:@supabase/supabase-js@2";
7	
8	const CAL_NAME = "St. Charles Co. Entitlement Dates";
9	const TZ = "America/Chicago";
10	const LOOKBACK_DAYS = 60;
11	
12	const VTIMEZONE = [
13	  "BEGIN:VTIMEZONE", "TZID:America/Chicago",
14	  "BEGIN:DAYLIGHT", "TZOFFSETFROM:-0600", "TZOFFSETTO:-0500", "TZNAME:CDT",
15	  "DTSTART:19700308T020000", "RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=2SU", "END:DAYLIGHT",
16	  "BEGIN:STANDARD", "TZOFFSETFROM:-0500", "TZOFFSETTO:-0600", "TZNAME:CST",
17	  "DTSTART:19701101T020000", "RRULE:FREQ=YEARLY;BYMONTH=11;BYDAY=1SU", "END:STANDARD",
18	  "END:VTIMEZONE",
19	];
20	
21	const esc = (s: string) =>
22	  s.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
23	
24	// RFC 5545 line folding: max 75 octets per line, continuation lines start with a space.
25	function fold(line: string): string {
26	  const bytes = new TextEncoder().encode(line);
27	  if (bytes.length <= 75) return line;
28	  const out: string[] = [];
29	  let cur = "", len = 0;
30	  for (const ch of line) {
31	    const n = new TextEncoder().encode(ch).length;
32	    if (len + n > (out.length ? 74 : 75)) { out.push(cur); cur = ""; len = 0; }
33	    cur += ch; len += n;
34	  }
35	  out.push(cur);
36	  return out.join("\r\n ");
37	}
38	
39	const ymd = (d: string) => d.replace(/-/g, "");
40	const hms = (t: string) => t.replace(/:/g, "").padEnd(6, "0").slice(0, 6);
41	const nextDay = (d: string) => {
42	  const x = new Date(d + "T00:00:00Z");
43	  x.setUTCDate(x.getUTCDate() + 1);
44	  return x.toISOString().slice(0, 10);
45	};
46	const fmtTime = (t: string) => {
47	  const [h, m] = t.split(":").map(Number);
48	  return `${h % 12 || 12}${m ? ":" + String(m).padStart(2, "0") : ""} ${h < 12 ? "AM" : "PM"}`;
49	};
50	
51	Deno.serve(async (req) => {
52	  const url = new URL(req.url);
53	  const expected = Deno.env.get("CALENDAR_TOKEN");
54	  if (!expected || url.searchParams.get("token") !== expected) {
55	    return new Response("Not found", { status: 404 });
56	  }
57	
58	  const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
59	  const since = new Date(Date.now() - LOOKBACK_DAYS * 864e5).toISOString().slice(0, 10);
60	  let q = db.from("meetings")
61	    .select("id, jurisdiction_id, body, event_type, event_date, event_time, location, note, status, source_url, jurisdictions!inner(name, governing_body, state)")
62	    .gte("event_date", since)
63	    .order("event_date");
64	  const only = url.searchParams.get("j");
65	  q = only ? q.in("jurisdiction_id", only.split(",").map((s) => s.trim())) : q.eq("jurisdictions.followed", true).eq("jurisdictions.state", "MO");
66	  const { data, error } = await q;
67	  if (error) return new Response("Error loading meetings", { status: 500 });
68	
69	  const stamp = new Date().toISOString().replace(/[-:]/g, "").slice(0, 15) + "Z";
70	  const lines = [
71	    "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//stl-zoning//Entitlement Tracker//EN",
72	    "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
73	    `X-WR-CALNAME:${CAL_NAME}`, `NAME:${CAL_NAME}`, `X-WR-TIMEZONE:${TZ}`,
74	    "REFRESH-INTERVAL;VALUE=DURATION:PT6H", "X-PUBLISHED-TTL:PT6H",
75	    ...VTIMEZONE,
76	  ];
77	
78	  for (const m of data ?? []) {
79	    // deno-lint-ignore no-explicit-any
80	    const j = (m as any).jurisdictions ?? {};
81	    const place = (j.name ?? m.jurisdiction_id).replace(/^(City|Town|Village) of /, "");
82	    const isDeadline = m.event_type === "submittal_deadline";
83	    let label = isDeadline ? "P&Z SUBMITTAL DUE"
84	      : m.body === "planning_zoning" ? "P&Z Meeting"
85	      : (j.governing_body ?? "Council").replace(/\s*\(.*\)$/, "");
86	    if (isDeadline && m.event_time) label += ` by ${fmtTime(m.event_time)}`;
87	    const prefix = m.status === "cancelled" ? "CANCELLED: " : m.status === "projected" ? "(Tentative) " : "";
88	
89	    const ev = [
90	      "BEGIN:VEVENT",
91	      `UID:meeting-${m.id}@stl-zoning`,
92	      `DTSTAMP:${stamp}`,
93	      `SUMMARY:${esc(`${prefix}${place} - ${label}`)}`,
94	    ];
95	    // Deadlines are all-day so they stand out; meetings with a known time are 2-hour blocks.
96	    if (isDeadline || !m.event_time) {
97	      ev.push(`DTSTART;VALUE=DATE:${ymd(m.event_date)}`, `DTEND;VALUE=DATE:${ymd(nextDay(m.event_date))}`, "TRANSP:TRANSPARENT");
98	    } else {
99	      const start = hms(m.event_time);
100	      const endH = String(Math.min(23, Number(start.slice(0, 2)) + 2)).padStart(2, "0");
101	      ev.push(`DTSTART;TZID=${TZ}:${ymd(m.event_date)}T${start}`, `DTEND;TZID=${TZ}:${ymd(m.event_date)}T${endH}${start.slice(2)}`);
102	    }
103	    if (m.location) ev.push(`LOCATION:${esc(m.location)}`);
104	    const desc = [m.note, m.status === "projected" ? "Projected from the usual pattern; not yet published." : null,
105	      m.source_url ? `Source: ${m.source_url}` : null].filter(Boolean).join("\n");
106	    if (desc) ev.push(`DESCRIPTION:${esc(desc)}`);
107	    if (m.source_url) ev.push(`URL:${m.source_url}`);
108	    ev.push(`STATUS:${m.status === "cancelled" ? "CANCELLED" : m.status === "projected" ? "TENTATIVE" : "CONFIRMED"}`);
109	    if (isDeadline) {
110	      ev.push("BEGIN:VALARM", "ACTION:DISPLAY", `DESCRIPTION:${esc(`${place} P&Z submittal due`)}`,
111	        "TRIGGER:-P3D", "END:VALARM");
112	    }
113	    ev.push("END:VEVENT");
114	    lines.push(...ev);
115	  }
116	  lines.push("END:VCALENDAR");
117	
118	  return new Response(lines.map(fold).join("\r\n") + "\r\n", {
119	    headers: {
120	      "Content-Type": "text/calendar; charset=utf-8",
121	      "Content-Disposition": 'inline; filename="entitlement-dates.ics"',
122	      "Cache-Control": "public, max-age=900",
123	    },
124	  });
125	});
