1	// Weekly email digest: the next two weeks of dates, overdue tasks, and what changed in the last 7 days.
2	// Sent through Resend to a distribution list. Triggered Mondays by pg_cron (see the change_log_and_digest migration).
3	//
4	// Secrets (Supabase dashboard → Edge Functions → Secrets):
5	//   RESEND_API_KEY  Resend API key
6	//   DIGEST_TO       recipient(s), comma-separated, e.g. the company distribution list
7	//   DIGEST_FROM     sender on a domain verified in Resend, e.g. "Entitlement Tracker <tracker@example.com>"
8	//   SITE_URL        optional, defaults to https://stl-zoning.vercel.app
9	//
10	// Requests need the x-digest-token header (value in public.app_settings). Add ?preview=1 to get the
11	// HTML back without sending, or ?to=someone@example.com to send a test to one address instead of the list.
12	// Deployed with verify_jwt off; the token guards access.
13	import { createClient } from "jsr:@supabase/supabase-js@2";
14	
15	const TZ = "America/Chicago";
16	const SITE = (Deno.env.get("SITE_URL") ?? "https://stl-zoning.vercel.app").replace(/\/$/, "");
17	
18	// deno-lint-ignore no-explicit-any
19	type Row = Record<string, any>;
20	
21	const todayCentral = () => new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date());
22	const addDays = (d: string, n: number) => {
23	  const x = new Date(d + "T00:00:00Z");
24	  x.setUTCDate(x.getUTCDate() + n);
25	  return x.toISOString().slice(0, 10);
26	};
27	const fmtDate = (d: string) =>
28	  new Intl.DateTimeFormat("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" }).format(new Date(d + "T00:00:00Z"));
29	const fmtTime = (t: string | null) => {
30	  if (!t) return "";
31	  const [h, m] = t.split(":").map(Number);
32	  return `${h % 12 || 12}${m ? ":" + String(m).padStart(2, "0") : ""} ${h < 12 ? "AM" : "PM"}`;
33	};
34	const esc = (s: unknown) =>
35	  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
36	const shortName = (n: string) => n.replace(/^(City|Town|Village) of /, "");
37	
38	const STAGE: Record<string, string> = {
39	  oyl: "OYL", prospect: "Prospect", loi: "LOI", diligence: "Diligence", development: "Development", closed: "Closed",
40	};
41	
42	const C = { teal: "#096764", amber: "#ffb549", orange: "#c4502a", green: "#2d6a3e", text: "#1d2a28", muted: "#5f6b67", border: "#e3e1da", bg: "#f6f5f1" };
43	const pill = (text: string, color: string) =>
44	  `<span style="display:inline-block;font-size:11px;font-weight:700;letter-spacing:.03em;padding:2px 8px;border-radius:99px;background:${color}1a;color:${color};white-space:nowrap">${esc(text)}</span>`;
45	const section = (title: string, body: string) =>
46	  `<tr><td style="padding:20px 24px 4px"><h2 style="margin:0 0 10px;font-size:16px;color:${C.text};border-bottom:2px solid ${C.amber};display:inline-block;padding-bottom:4px">${esc(title)}</h2>${body}</td></tr>`;
47	const list = (items: string[], empty: string) =>
48	  items.length
49	    ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">${items.join("")}</table>`
50	    : `<p style="margin:0;color:${C.muted};font-size:14px">${esc(empty)}</p>`;
51	const li = (left: string, right: string) =>
52	  `<tr><td style="padding:6px 10px 6px 0;vertical-align:top;white-space:nowrap;font-size:13px;color:${C.muted};width:92px">${left}</td><td style="padding:6px 0;font-size:14px;color:${C.text};border-bottom:1px solid ${C.border}">${right}</td></tr>`;
53	
54	Deno.serve(async (req) => {
55	  const url = new URL(req.url);
56	  const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
57	
58	  const { data: tok } = await db.from("app_settings").select("value").eq("key", "digest_token").single();
59	  if (!tok || req.headers.get("x-digest-token") !== tok.value) return new Response("Not found", { status: 404 });
60	
61	  const today = todayCentral();
62	  const horizon = addDays(today, 14);
63	  const weekAgo = new Date(Date.now() - 7 * 864e5).toISOString();
64	
65	  const [{ data: js }, { data: meetings }, { data: tasks }, { data: changes }, { data: projects }, { data: sources }, { data: timeline }] = await Promise.all([
66	    // The digest goes to Lombardo, so Missouri only (other states are collected for the public product).
67	    db.from("jurisdictions").select("id, name, governing_body, followed, state"),
68	    db.from("meetings").select("*, jurisdictions!inner(followed, state)").eq("jurisdictions.followed", true).eq("jurisdictions.state", "MO").gte("event_date", today).lte("event_date", horizon).neq("status", "cancelled")
69	      .order("event_date").order("event_time"),
70	    db.from("tasks").select("id, title, assigned_to, due_date, project_id").is("done_at", null)
71	      .not("due_date", "is", null).lte("due_date", horizon).order("due_date"),
72	    db.from("change_log").select("*").gte("at", weekAgo).order("at"),
73	    db.from("projects").select("id, name"),
74	    // Same rule as needsReview in web/src/app/sources/review.ts; check-sources runs an hour before this.
75	    db.from("source_watches").select("jurisdiction_id, url, label, last_status, last_changed_at, change_summary, reviewed_at, jurisdictions!inner(followed, state)")
76	      .eq("jurisdictions.followed", true).eq("jurisdictions.state", "MO").not("last_changed_at", "is", null).order("jurisdiction_id"),
77	    // Logged delays and possible delays from agendas/minutes (each was also emailed when posted, by project-alerts).
78	    db.from("project_alerts").select("project_id, kind, title, body, created_at").gte("created_at", weekAgo).order("created_at"),
79	  ]);
80	  const jmap = new Map((js ?? []).map((j: Row) => [j.id, j]));
81	  const pmap = new Map((projects ?? []).map((p: Row) => [p.id, p.name]));
82	  const place = (id: string) => esc(shortName(jmap.get(id)?.name ?? id));
83	  const gov = (id: string) => (jmap.get(id)?.governing_body ?? "Council").replace(/\s*\(.*\)$/, "");
84	  const link = (path: string, text: string) => `<a href="${SITE}${path}" style="color:${C.teal};text-decoration:none;font-weight:600">${text}</a>`;
85	
86	  // ---- Coming up (next 14 days)
87	  const deadlines = (meetings ?? []).filter((m: Row) => m.event_type === "submittal_deadline");
88	  const hearings = (meetings ?? []).filter((m: Row) => m.event_type === "meeting");
89	  const meetingLine = (m: Row) => {
90	    const kind = m.body === "planning_zoning" ? pill("P&Z", C.teal) : pill(gov(m.jurisdiction_id).toUpperCase(), C.green);
91	    const tentative = m.status === "projected" ? ` ${pill("tentative", "#8a5a00")}` : "";
92	    return li(fmtDate(m.event_date), `${kind} ${link(`/jurisdictions/${m.jurisdiction_id}`, place(m.jurisdiction_id))}${m.event_time ? ` · ${fmtTime(m.event_time)}` : ""}${tentative}`);
93	  };
94	  const deadlineLine = (m: Row) =>
95	    li(fmtDate(m.event_date), `${pill("SUBMITTAL DUE", C.orange)} ${link(`/jurisdictions/${m.jurisdiction_id}`, place(m.jurisdiction_id))}${m.event_time ? ` by ${fmtTime(m.event_time)}` : ""}`);
96	
97	  const overdue = (tasks ?? []).filter((t: Row) => t.due_date < today);
98	  const dueSoon = (tasks ?? []).filter((t: Row) => t.due_date >= today);
99	  const taskLine = (t: Row) =>
100	    li(fmtDate(t.due_date), `${esc(t.title)} <span style="color:${C.muted}">— ${esc(t.assigned_to ?? "Unassigned")}${t.project_id ? ` · ${esc(pmap.get(t.project_id) ?? "")}` : ""}</span>`);
101	
102	  // ---- What changed (last 7 days)
103	  const changeLines: string[] = [];
104	  const newDates = new Map<string, number>();
105	  for (const c of (changes ?? []) as Row[]) {
106	    const o = c.old_row ?? {}, n = c.new_row ?? {};
107	    const when = fmtDate(new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date(c.at)));
108	    if (c.table_name === "meetings") {
109	      const r = c.action === "delete" ? o : n;
110	      if (jmap.get(r.jurisdiction_id)?.followed === false || (jmap.get(r.jurisdiction_id)?.state ?? "MO") !== "MO") continue;
111	      const what = r.event_type === "submittal_deadline" ? "submittal deadline" : r.body === "planning_zoning" ? "P&Z meeting" : gov(r.jurisdiction_id);
112	      if (c.action === "insert") { newDates.set(r.jurisdiction_id, (newDates.get(r.jurisdiction_id) ?? 0) + 1); continue; }
113	      if (c.action === "delete") { changeLines.push(li(when, `${pill("REMOVED", C.orange)} ${place(r.jurisdiction_id)} ${esc(what)} on ${fmtDate(r.event_date)}`)); continue; }
114	      if (n.status === "cancelled" && o.status !== "cancelled") {
115	        changeLines.push(li(when, `${pill("CANCELLED", C.orange)} ${place(n.jurisdiction_id)} ${esc(what)} on ${fmtDate(n.event_date)}`));
116	      } else if (o.event_date !== n.event_date || o.event_time !== n.event_time) {
117	        changeLines.push(li(when, `${pill("MOVED", "#8a5a00")} ${place(n.jurisdiction_id)} ${esc(what)}: ${fmtDate(o.event_date)} ${fmtTime(o.event_time)} → <strong>${fmtDate(n.event_date)} ${fmtTime(n.event_time)}</strong>`));
118	      } else if (o.status === "projected" && n.status === "published") {
119	        changeLines.push(li(when, `${pill("CONFIRMED", C.green)} ${place(n.jurisdiction_id)} ${esc(what)} on ${fmtDate(n.event_date)}`));
120	      } else if (o.location !== n.location) {
121	        changeLines.push(li(when, `${pill("NEW LOCATION", "#8a5a00")} ${place(n.jurisdiction_id)} ${esc(what)} on ${fmtDate(n.event_date)}: ${esc(n.location)}`));
122	      }
123	    } else if (c.table_name === "projects") {
124	      if (c.action === "insert") changeLines.push(li(when, `${pill("NEW PROJECT", C.teal)} ${link(`/projects/${n.id}`, esc(n.name))}`));
125	      else if (c.action === "update" && o.stage !== n.stage)
126	        changeLines.push(li(when, `${pill("STAGE", C.teal)} ${link(`/projects/${n.id}`, esc(n.name))}: ${esc(STAGE[o.stage] ?? o.stage)} → <strong>${esc(STAGE[n.stage] ?? n.stage)}</strong>`));
127	    } else if (c.table_name === "tasks") {
128	      if (c.action === "insert") changeLines.push(li(when, `${pill("NEW TASK", "#9a5a00")} ${esc(n.title)} <span style="color:${C.muted}">— ${esc(n.assigned_to ?? "Unassigned")}</span>`));
129	      else if (c.action === "update" && !o.done_at && n.done_at) changeLines.push(li(when, `${pill("DONE", C.green)} ${esc(n.title)}`));
130	    }
131	  }
132	  for (const [jid, count] of newDates) {
133	    changeLines.unshift(li("This week", `${pill("NEW DATES", C.teal)} ${count} date${count === 1 ? "" : "s"} added for ${link(`/jurisdictions/${jid}`, place(jid))}`));
134	  }
135	
136	  // ---- Project timeline changes (last 7 days)
137	  const timelineLines = ((timeline ?? []) as Row[]).map((a) =>
138	    li(fmtDate(new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date(a.created_at))),
139	      `${a.kind === "delay" ? pill("DELAY", C.orange) : pill("POSSIBLE DELAY", "#8a5a00")} ${link(`/projects/${a.project_id}`, esc(a.title))}` +
140	      (a.body ? `<div style="color:${C.muted};font-size:13px;margin-top:2px">${esc(a.body)}</div>` : "")));
141	
142	  // ---- Schedule sources that changed and nobody has marked reviewed on /sources
143	  const toReview = ((sources ?? []) as Row[]).filter((w) => !w.reviewed_at || w.reviewed_at < w.last_changed_at);
144	  const sourceLines = toReview.map((w) => {
145	    const when = fmtDate(new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date(w.last_changed_at)));
146	    const status = w.last_status && w.last_status !== 200 ? ` ${pill(`HTTP ${w.last_status}`, C.orange)}` : "";
147	    return li(when, `${place(w.jurisdiction_id)}: <a href="${esc(w.url)}" style="color:${C.teal}">${esc(w.label ?? "source")}</a>${status}` +
148	      (w.change_summary ? ` <span style="color:${C.muted}">— ${esc(w.change_summary)}</span>` : ""));
149	  });
150	
151	  const subject = `Entitlement dates: week of ${fmtDate(today)}` +
152	    (deadlines.length ? ` · ${deadlines.length} submittal deadline${deadlines.length === 1 ? "" : "s"}` : "");
153	
154	  const html = `<!doctype html><html><body style="margin:0;background:${C.bg};font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif">
155	<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.bg};padding:24px 12px"><tr><td align="center">
156	<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#fff;border:1px solid ${C.border};border-radius:12px;overflow:hidden">
157	<tr><td style="padding:18px 24px;border-bottom:3px solid ${C.amber}">
158	  <img src="${SITE}/lombardo-logo.png" alt="Lombardo Homes" width="142" height="40" style="vertical-align:middle">
159	  <span style="vertical-align:middle;margin-left:12px;padding-left:12px;border-left:1px solid ${C.border};color:#8f9a8e;font-weight:700;font-size:15px">Entitlement Tracker</span>
160	</td></tr>
161	<tr><td style="padding:20px 24px 0"><h1 style="margin:0;font-size:22px;color:${C.text}">Week of ${fmtDate(today)}</h1>
162	<p style="margin:6px 0 0;color:${C.muted};font-size:14px">${deadlines.length} submittal deadline${deadlines.length === 1 ? "" : "s"}, ${hearings.length} meeting${hearings.length === 1 ? "" : "s"} and ${dueSoon.length + overdue.length} open task${dueSoon.length + overdue.length === 1 ? "" : "s"} in the next two weeks.</p></td></tr>
163	${section("Submittal deadlines — next 2 weeks", list(deadlines.map(deadlineLine), "No submittal deadlines in the next two weeks."))}
164	${section("Meetings — next 2 weeks", list(hearings.map(meetingLine), "No meetings in the next two weeks."))}
165	${overdue.length ? section("Overdue tasks", list(overdue.map(taskLine), "")) : ""}
166	${section("Tasks due — next 2 weeks", list(dueSoon.map(taskLine), "No tasks due."))}
167	${timelineLines.length ? section("Project timeline changes", list(timelineLines, "")) : ""}
168	${section("What changed this week", list(changeLines, "No changes this week."))}
169	${sourceLines.length ? section(`Schedule sources to review (${sourceLines.length})`, list(sourceLines, "") +
170	  `<p style="margin:8px 0 0;font-size:13px">${link("/sources", "Review them on the Sources page")}</p>`) : ""}
171	<tr><td style="padding:24px">
172	  <a href="${SITE}/" style="display:inline-block;background:${C.teal};color:#fff;text-decoration:none;font-weight:700;padding:10px 18px;border-radius:7px;font-size:14px">Open the calendar</a>
173	  <a href="${SITE}/subscribe" style="margin-left:14px;color:${C.teal};font-size:13px">Add these dates to your calendar</a>
174	</td></tr>
175	</table>
176	<p style="color:${C.muted};font-size:12px;margin:12px 0 0">Sent every Monday by the Entitlement Tracker.</p>
177	</td></tr></table></body></html>`;
178	
179	  if (url.searchParams.get("preview")) {
180	    return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8" } });
181	  }
182	
183	  const key = Deno.env.get("RESEND_API_KEY");
184	  const from = Deno.env.get("DIGEST_FROM");
185	  const to = (url.searchParams.get("to") ?? Deno.env.get("DIGEST_TO") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
186	  const missing = [!key && "RESEND_API_KEY", !from && "DIGEST_FROM", !to.length && "DIGEST_TO"].filter(Boolean);
187	  if (missing.length) {
188	    return new Response(`Missing secret: ${missing.join(", ")}`, { status: 500 });
189	  }
190	
191	  const res = await fetch("https://api.resend.com/emails", {
192	    method: "POST",
193	    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
194	    body: JSON.stringify({ from, to, subject, html }),
195	  });
196	  const out = await res.json().catch(() => ({}));
197	  await db.from("digest_log").insert({
198	    recipients: to.join(", "),
199	    resend_id: out?.id ?? null,
200	    error: res.ok ? null : JSON.stringify(out).slice(0, 1000),
201	  });
202	  return new Response(JSON.stringify({ ok: res.ok, id: out?.id, error: res.ok ? undefined : out }), {
203	    status: res.ok ? 200 : 502,
204	    headers: { "Content-Type": "application/json" },
205	  });
206	});
