112	  const api = (path: string, q: Record<string, string | number> = {}) =>
113	    `https://${tenant}.api.civicclerk.com/v1/${path}?` + Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(String(v))}`).join("&");
114	  const flt = `startDateTime ge ${year}-01-01T00:00:00Z and startDateTime lt ${year + 1}-01-01T00:00:00Z`;
115	  // deno-lint-ignore no-explicit-any
116	  const events: any[] = [];
117	  for (;;) { // 15 per page whatever $top says
118	    const { text } = await fetchText(api("Events", { $filter: flt, $orderby: "startDateTime", $skip: events.length }));
119	    const page = JSON.parse(text).value ?? [];
120	    if (!page.length) break;
121	    events.push(...page);
122	    if (events.length > 2000) break;
123	  }
124	  const rows = new Map<string, Collected>();
125	  for (const e of events) {
126	    const body = bodyFor(e.categoryName ?? e.eventCategoryName ?? "");
127	    if (!body || notHearing(e.eventName) || e.isDeleted) continue;
128	    const local: string = e.startDateTime.slice(0, 16);
129	    // deno-lint-ignore no-explicit-any
130	    const file = (type: string) => (e.publishedFiles ?? []).find((f: any) => f.type === type);
131	    const fileUrl = (f: { fileId: number } | undefined) =>
132	      f ? api(`Meetings/GetMeetingFileStream(fileId=${f.fileId},plainText=false)`).replace(/\?$/, "") : null;
133	    const loc = e.eventLocation ?? {};
134	    const time = local.slice(11, 16);
135	    keep(rows, {
136	      body, event_date: local.slice(0, 10), event_time: time && time !== "00:00" ? time : null,
137	      location: [loc.address1, loc.address2].filter(Boolean).join(", ") || null,
138	      title: e.eventName,
139	      agenda_url: fileUrl(file("Agenda")), packet_url: fileUrl(file("Agenda Packet")), minutes_url: fileUrl(file("Minutes")),
140	      source_url: `https://${tenant}.portal.civicclerk.com/event/${e.id}/files`, cancelled: CANCELLED.test(e.eventName),
141	    });
142	  }
143	  return [...rows.values()];
144	}
