187	// ---- Legistar (webapi.legistar.com/v1/<client>): public API with the whole schedule, agenda and minutes PDFs.
188	// Columbus votes on rezonings with City Council sitting as its Zoning Committee, the same evening as the regular
189	// council meeting, so that committee counts as the governing body and wins the date.
190	const ZONING_COMMITTEE = /^zoning committee$/i;
191	const clock = (t: string | null) => {
192	  const m = t?.match(/(\d{1,2}):(\d{2})\s*([AP])M/i);
193	  if (!m) return null;
194	  const h = (Number(m[1]) % 12) + (m[3].toUpperCase() === "P" ? 12 : 0);
195	  return `${String(h).padStart(2, "0")}:${m[2]}`;
196	};
197	
198	async function legistar(client: string, year: number): Promise<Collected[]> {
199	  const flt = `EventDate ge datetime'${year}-01-01' and EventDate lt datetime'${year + 1}-01-01'`;
200	  const { text } = await fetchText(`https://webapi.legistar.com/v1/${client}/events?$filter=${encodeURIComponent(flt)}&$orderby=EventDate`, undefined, "application/json");
201	  const rows = new Map<string, Collected>();
202	  const zoningDates = new Set<string>();
203	  // deno-lint-ignore no-explicit-any
204	  for (const e of JSON.parse(text) as any[]) {
205	    const name: string = (e.EventBodyName ?? "").trim();
206	    const zc = ZONING_COMMITTEE.test(name);
207	    const body = zc ? "governing_body" : bodyFor(name);
208	    const title = [name, e.EventComment].filter(Boolean).join(" - ");
209	    if (!body || notHearing(title)) continue;
210	    const c: Collected = {
211	      body, event_date: String(e.EventDate).slice(0, 10), event_time: clock(e.EventTime), location: e.EventLocation || null, title,
212	      agenda_url: e.EventAgendaFile || null, packet_url: null, minutes_url: e.EventMinutesFile || null,
213	      source_url: e.EventInSiteURL || `https://${client}.legistar.com/Calendar.aspx`,
214	      cancelled: CANCELLED.test(`${title} ${e.EventAgendaStatusName ?? ""}`),
215	    };
216	    if (zc && !c.cancelled) {
217	      rows.delete(`${body}|${c.event_date}`);
218	      zoningDates.add(c.event_date);
219	    } else if (!zc && zoningDates.has(c.event_date)) continue;
220	    keep(rows, c);
221	  }
222	  return [...rows.values()];
223	}
