225	// ---- Granicus ViewPublisher (<client>.granicus.com/ViewPublisher.php?view_id=1): one page with upcoming events
226	// (no links yet) and every past meeting by board and year, linking agenda, minutes and packet PDFs.
227	// The ref is the subdomain, optionally with the view: "delawareohio" or "delawareohio/2".
228	const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
229	
230	async function granicus(ref: string, year: number): Promise<Collected[]> {
231	  const [client, view = "1"] = ref.split("/");
232	  const source = `https://${client}.granicus.com/ViewPublisher.php?view_id=${view}`;
233	  const { text: page } = await fetchText(source);
234	  const rows = new Map<string, Collected>();
235	  for (const r of page.matchAll(/<tr class="listingRow">([\s\S]*?)<\/tr>/g)) {
236	    const row = unescape(r[1]).replace(/\s+/g, " ");
237	    const name = row.match(/headers="Name"[^>]*>([^<]*)</)?.[1].trim() ?? "";
238	    const when = row.match(/headers="Date[^"]*">\s*([A-Z][a-z]{2})\s*(\d{1,2}),\s*(\d{4})(?:\s*-\s*(\d{1,2}:\d{2}\s*[AP]M))?/);
239	    const body = bodyFor(name);
240	    if (!body || !when || Number(when[3]) !== year || notHearing(name)) continue;
241	    const date = `${when[3]}-${String(MONTHS.indexOf(when[1].toLowerCase()) + 1).padStart(2, "0")}-${when[2].padStart(2, "0")}`;
242	    const link = (re: RegExp) => {
243	      const href = row.match(re)?.[1];
244	      return href ? (href.startsWith("//") ? "https:" + href : href) : null;
245	    };
246	    const c: Collected = {
247	      body, event_date: date, event_time: clock(when[4] ?? null), location: null, title: name,
248	      agenda_url: link(/href="([^"]*AgendaViewer\.php[^"]*)"/), packet_url: link(/href="([^"]+)"[^>]*>\s*Agenda Packet/),
249	      minutes_url: link(/href="([^"]*MinutesViewer\.php[^"]*)"/), source_url: source, cancelled: CANCELLED.test(name),
250	    };
251	    // The same meeting can be listed under Upcoming Events (no links) and in the archive (links): merge them.
252	    const prev = rows.get(`${body}|${date}`);
253	    if (prev) {
254	      prev.agenda_url ??= c.agenda_url; prev.packet_url ??= c.packet_url; prev.minutes_url ??= c.minutes_url; prev.event_time ??= c.event_time;
255	    } else keep(rows, c);
256	  }
257	  return [...rows.values()];
258	}
