260	// ---- CivicWeb (<client>.civicweb.net): a JSON meeting list, then each P&Z / council meeting's documents
261	// (Type 1 = agenda, as HTML (DocumentType 1) and the PDF packet (DocumentType 4); Type 2 = minutes).
262	async function civicWeb(client: string, year: number): Promise<Collected[]> {
263	  const base = `https://${client}.civicweb.net`;
264	  const { text } = await fetchText(`${base}/Services/MeetingsService.svc/meetings?from=${year}-01-01&to=${year}-12-31`, undefined, "application/json");
265	  const rows = new Map<string, Collected>();
266	  // deno-lint-ignore no-explicit-any
267	  for (const m of JSON.parse(text) as any[]) {
268	    const title = unescape(m.Name ?? "").trim();
269	    const body = bodyFor(title.split(" - ")[0]);
270	    if (!body || notHearing(title)) continue;
271	    // deno-lint-ignore no-explicit-any
272	    let docs: any[] = [];
