281	      agenda_url: doc(1, 1) ?? doc(1), packet_url: doc(1, 4), minutes_url: doc(2),
282	      source_url: `${base}/Portal/MeetingInformation.aspx?Id=${m.Id}`, cancelled: CANCELLED.test(title),
283	    });
