288	// ---- Cities that post meetings on their own web pages. The ref names one page per board, with the board's usual
289	// start time when the page doesn't give one: "pz=<url>#19:00 gov=<url>".
290	const pages = (ref: string) =>
291	  ref.split(/\s+/).filter(Boolean).map((p) => {
292	    const [, k, url, time] = p.match(/^(\w+)=([^#]+)(?:#(\d{2}:\d{2}))?$/)!;
293	    return { body: (k === "pz" ? "planning_zoning" : "governing_body") as Body, url, time: time ?? null };
294	  });
295	const MONTH_DAY = /\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,\s*(\d{3,4}))?/i;
296	const ymdOf = (m: RegExpMatchArray, year: number) => {
297	  // "February 26, 202" (a typo on the page) falls back to the page's year.
298	  const y = m[3]?.length === 4 ? Number(m[3]) : year;
299	  return `${y}-${String(MONTHS.indexOf(m[1].slice(0, 3).toLowerCase()) + 1).padStart(2, "0")}-${m[2].padStart(2, "0")}`;
300	};
301	// "7 p.m.", "6:30 p.m.", "3 PM" -> "19:00"
302	const clockText = (s: string) => {
303	  const m = s.match(/(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s*m\b/i);
304	  if (!m) return null;
305	  const h = (Number(m[1]) % 12) + (m[3].toLowerCase() === "p" ? 12 : 0);
306	  return `${String(h).padStart(2, "0")}:${m[2] ?? "00"}`;
307	};
308	const linkTo = (html: string, label: RegExp, base: string) => {
309	  for (const a of html.matchAll(/<a\s[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g)) {
310	    if (label.test(a[2].replace(/<[^>]+>/g, ""))) return new URL(unescape(a[1]), base).href;
311	  }
312	  return null;
313	};
314	const plain = (html: string) => unescape(html.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
315	const SIDE_EVENT = /workshop|interview|reception|retreat|training|joint/i;
316	
317	// Dublin (dublinohiousa.gov): an <h4> per date ("Monday, Oct. 26"), then a <p> per meeting ("Executive Session | 5:30 p.m.
318	// Regular Meeting | 7 p.m. | Council Chamber Agenda | Watch | Action | Minutes"). Dates leave the year off unless it
319	// differs from the page's ("2026 Meetings"). The council page's committee schedule (the <h3> after) is left out.
320	async function dublin(ref: string, year: number): Promise<Collected[]> {
321	  const rows = new Map<string, Collected>();
322	  for (const { body, url } of pages(ref)) {
323	    const { text } = await fetchText(url);
324	    const h3 = [...text.matchAll(/<h3[^>]*>([\s\S]*?)<\/h3>/g)];
325	    const pageYear = Number(plain(h3[0]?.[1] ?? "").match(/\d{4}/)?.[0] ?? year);
326	    const end = h3.find((h) => /committee/i.test(plain(h[1])))?.index ?? text.length;
327	    for (const b of text.slice(0, end).matchAll(/<h4[^>]*>([\s\S]*?)<\/h4>([\s\S]*?)(?=<h[1-4][\s>]|$)/g)) {
328	      const when = plain(b[1]).match(new RegExp("^[A-Z][a-z]+day,\\s*" + MONTH_DAY.source.slice(2), "i"));
329	      if (!when) continue;
330	      const date = ymdOf(when, pageYear);
331	      if (Number(date.slice(0, 4)) !== year) continue;
332	      for (const seg of b[2].split(/<\/p>/)) {
333	        const text = plain(seg);
334	        // The meeting's own name is the last "<name> | <time>" in the segment ("Executive Session | 5:30 p.m. Regular Meeting | 7 p.m.").
335	        const named = [...text.matchAll(/([A-Z][A-Za-z/&' ]*?)\s*\|\s*(\d{1,2}(?::\d{2})?\s*[ap]\.m\.|\[?Meeting Cancelled)/g)].pop();
336	        if (!named) continue;
337	        const title = named[1].trim();
338	        const agenda = linkTo(seg, /agenda/i, url);
339	        if (!/regular|special|organizational/i.test(title) || notHearing(title) || SIDE_EVENT.test(title) || /training/i.test(agenda ?? "")) continue;
340	        keep(rows, {
341	          body, event_date: date, event_time: clockText(named[2]), location: null, title,
342	          agenda_url: agenda, packet_url: null, minutes_url: linkTo(seg, /minutes/i, url), source_url: url,
343	          cancelled: CANCELLED.test(text),
344	        });
345	      }
346	    }
347	  }
348	  return [...rows.values()];
349	}
