351	// A table per board with a header row naming its columns (Date | Agenda | Minutes | Meeting Packet), one row per
352	// meeting: "Monday, October 19, 2026" or "October 6, 2026 3 PM Executive Session". New Albany.
353	async function pageTable(ref: string, year: number): Promise<Collected[]> {
354	  const rows = new Map<string, Collected>();
355	  for (const { body, url, time } of pages(ref)) {
356	    const { text } = await fetchText(url);
357	    for (const t of text.matchAll(/<table[\s\S]*?<\/table>/g)) {
358	      const trs = [...t[0].matchAll(/<tr[\s\S]*?<\/tr>/g)].map((r) => [...r[0].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/g)].map((c) => c[1]));
359	      const head = trs[0]?.map(plain) ?? [];
360	      const col = (re: RegExp) => head.findIndex((h) => re.test(h));
361	      const [ai, mi, pi] = [col(/agenda/i), col(/minutes/i), col(/packet/i)];
362	      if (ai < 0) continue;
363	      for (const cells of trs.slice(1)) {
364	        const first = plain(cells[0] ?? "");
365	        const when = first.match(MONTH_DAY);
366	        if (!when || when.index! > 12 || when[3]?.length !== 4 || Number(when[3]) !== year) continue;
367	        const title = first.slice(when.index! + when[0].length).trim();
368	        if (notHearing(title) || SIDE_EVENT.test(title)) continue;
369	        const cell = (i: number) => (i >= 0 ? cells[i] ?? "" : "");
370	        keep(rows, {
371	          body, event_date: ymdOf(when, year), event_time: clockText(title) ?? time, location: null, title: title || first,
372	          agenda_url: linkTo(cell(ai), /./, url), packet_url: linkTo(cell(pi), /packet/i, url),
373	          minutes_url: linkTo(cell(mi), /minutes/i, url), source_url: url, cancelled: CANCELLED.test(plain(cell(ai)) + title),
374	        });
375	      }
376	    }
377	  }
378	  return [...rows.values()];
379	}
