381	// Delaware County Regional Planning Commission: the year's dates laid out in grids, one grid per kind of document
382	// ("2026 Preliminary Agendas", "2026 Meeting Minutes", and the staff Technical Review Committee's, which is skipped).
383	// Every date is a meeting; it's a link once that document is posted. Meetings are 6 p.m. at the Byxbe Building.
384	async function dcrpc(url: string, year: number): Promise<Collected[]> {
385	  const { text } = await fetchText(url);
386	  const rows = new Map<string, Collected>();
387	  for (const t of text.matchAll(/<table[\s\S]*?<\/table>/g)) {
388	    const heading = plain(t[0].match(/<th[^>]*>([\s\S]*?)<\/th>/)?.[1] ?? "");
389	    if (!heading.includes(String(year)) || /technical review/i.test(heading)) continue;
390	    const kind = /minutes/i.test(heading) ? "minutes_url" : /agenda/i.test(heading) ? "agenda_url" : null;
391	    if (!kind) continue;
392	    for (const c of t[0].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)) {
393	      const when = plain(c[1]).match(MONTH_DAY);
394	      if (!when) continue;
395	      const date = ymdOf(when, year);
396	      const href = c[1].match(/href="([^"]+\.pdf)"/i)?.[1] ?? null;
397	      const row = rows.get(date) ?? {
398	        body: "planning_zoning" as Body, event_date: date, event_time: "18:00", location: "Byxbe Building, 1610 State Route 521, Delaware",
399	        title: "Regional Planning Commission", agenda_url: null, packet_url: null, minutes_url: null, source_url: url, cancelled: false,
400	      };
401	      // January's minutes link points at that month's agenda.
402	      if (href !== row.agenda_url) row[kind] ??= href;
403	      rows.set(date, row);
404	    }
405	  }
406	  return [...rows.values()];
407	}
