409	const COLLECTORS: Record<string, (ref: string, year: number) => Promise<Collected[]>> = {
410	  agendacenter: agendaCenter, civicclerk: civicClerk, municode: municodeMeetings, legistar, granicus, civicweb: civicWeb,
411	  dublin, pagetable: pageTable, dcrpc,
