414	Deno.serve(async (req) => {
415	  const url = new URL(req.url);
416	  const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
417	  const { data: tok } = await db.from("app_settings").select("value").eq("key", "digest_token").single();
418	  if (!tok || req.headers.get("x-digest-token") !== tok.value) return new Response("Not found", { status: 404 });
419	
420	  const today = new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date());
421	  const year = Number(today.slice(0, 4));
422	  // Late in the year, also pick up next year's meetings as cities post them. ?years=2021,2022 backfills past years
423	  // (one jurisdiction and year per call keeps CivicClerk's 15-per-page paging under the time limit).
424	  const asked = (url.searchParams.get("years") ?? "").split(",").map(Number).filter((y) => y >= 2000 && y <= year + 1);
425	  const years = asked.length ? asked.sort((a, b) => a - b) : Number(today.slice(5, 7)) >= 11 ? [year, year + 1] : [year];
426	
427	  let q = db.from("jurisdictions").select("id, collector, collector_ref").not("collector", "is", null);
428	  const only = url.searchParams.get("j");
429	  q = only ? q.eq("id", only) : q.eq("followed", true);
430	  const { data: js, error } = await q;
431	  if (error) return new Response(error.message, { status: 500 });
432	
433	  const runOne = async (j: { id: string; collector: string; collector_ref: string }) => {
434	    const fullSchedule = j.collector !== "agendacenter";
435	    try {
436	      const collected: Collected[] = [];
437	      for (const y of years) {
438	        collected.push(...await COLLECTORS[j.collector](j.collector_ref, y));
439	      }
440	      const { data: existing } = await db.from("meetings")
441	        .select("id, body, event_date, event_time, location, agenda_url, packet_url, minutes_url, status")
442	        .eq("jurisdiction_id", j.id).eq("event_type", "meeting")
443	        .gte("event_date", `${years[0]}-01-01`).lte("event_date", `${years[years.length - 1]}-12-31`);
444	      const have = new Map((existing ?? []).map((m) => [`${m.body}|${m.event_date}`, m]));
445	      const seen = new Set(collected.map((c) => `${c.body}|${c.event_date}`));
446	
447	      const inserts = [];
448	      let updated = 0;
449	      for (const c of collected) {
450	        const m = have.get(`${c.body}|${c.event_date}`);
451	        if (!m) {
452	          inserts.push({
453	            jurisdiction_id: j.id, body: c.body, event_type: "meeting", event_date: c.event_date, event_time: c.event_time,
454	            location: c.location, status: c.cancelled ? "cancelled" : "published", source_url: c.source_url,
455	            agenda_url: c.agenda_url, packet_url: c.packet_url, minutes_url: c.minutes_url, verified_on: today,
456	            note: /special/i.test(c.title) ? "Special meeting" : null,
457	          });
458	          continue;
459	        }
460	        const patch: Record<string, unknown> = {};
461	        if (!m.agenda_url && c.agenda_url) patch.agenda_url = c.agenda_url;
462	        // A different agenda link for an upcoming meeting is usually an amended agenda; extract-agendas' recheck
463	        // sees the new file and reads it again.
464	        else if (m.agenda_url && c.agenda_url && c.agenda_url !== m.agenda_url && c.event_date >= today) patch.agenda_url = c.agenda_url;
465	        if (!m.packet_url && c.packet_url) patch.packet_url = c.packet_url;
466	        if (!m.minutes_url && c.minutes_url) patch.minutes_url = c.minutes_url;
467	        if (!m.event_time && c.event_time) patch.event_time = c.event_time;
468	        if (!m.location && c.location) patch.location = c.location;
469	        if (m.status === "projected" && c.cancelled) patch.status = "cancelled";
470	        else if (m.status === "projected" && (c.agenda_url || fullSchedule)) patch.status = "published";
471	        if (Object.keys(patch).length) {
472	          patch.verified_on = today;
473	          const { error: ue } = await db.from("meetings").update(patch).eq("id", m.id);
474	          if (ue) throw new Error(ue.message);
475	          updated++;
476	        }
477	      }
478	      if (inserts.length) {
479	        const { error: ie } = await db.from("meetings").insert(inserts);
480	        if (ie) throw new Error(ie.message);
481	      }
482	      // CivicClerk and Municode list the whole schedule, so anything they lack is suspect. AgendaCenter only
483	      // lists posted agendas, so only past meetings (a few days' grace) count there.
484	      const cutoff = fullSchedule ? "9999-12-31" : new Date(Date.now() - 3 * 864e5).toISOString().slice(0, 10);
485	      const missing = collected.length
486	        ? (existing ?? []).filter((m) => m.status !== "cancelled" && m.event_date <= cutoff && !seen.has(`${m.body}|${m.event_date}`))
487	          .map((m) => ({ event_date: m.event_date, body: m.body }))
488	        : [];
489	      await db.from("jurisdictions").update({ collected_on: new Date().toISOString() }).eq("id", j.id);
490	      const run = { jurisdiction_id: j.id, ok: true, found: collected.length, inserted: inserts.length, updated, missing: missing.length ? missing : null };
491	      await db.from("collector_runs").insert(run);
492	      return run;
493	    } catch (e) {
494	      const run = { jurisdiction_id: j.id, ok: false, error: String((e as Error).message ?? e).slice(0, 500) };
495	      await db.from("collector_runs").insert(run);
496	      return run;
497	    }
498	  };
499	
500	  // A few sites at a time, to stay polite to small-town web servers.
501	  const results: unknown[] = [];
502	  const queue = [...(js ?? [])];
503	  await Promise.all(Array.from({ length: 6 }, async () => {
504	    for (let j = queue.shift(); j; j = queue.shift()) results.push(await runOne(j));
505	  }));
506	  return new Response(JSON.stringify(results, null, 1), { headers: { "Content-Type": "application/json" } });
507	});
508

