// The public front door and the open demo (no sign-up). Kept free of next/headers so middleware can use it.
// "Project Hawkeye" is a working name for the public product until it gets a real one.
export const PRODUCT = "Project Hawkeye";
export const DEMO_COOKIE = "demo";

// Pages outside the Lombardo site: no Lombardo header, open to anyone.
export const PUBLIC_PAGES = ["/welcome", "/signup"];

// What a demo visitor can open. Everything else is Lombardo's own work (projects, tasks, suggestions, alerts).
const DEMO_PAGES = ["/rezonings", "/votes", "/meetings", "/jurisdictions", "/directory"];
const ALWAYS_OPEN = [...PUBLIC_PAGES, "/demo", "/login", "/auth", "/calendar.ics"];

const under = (path: string, base: string) => path === base || path.startsWith(base + "/");

export const isPublicPage = (path: string) => PUBLIC_PAGES.some((p) => under(path, p));

export function demoAllows(path: string) {
  if (path === "/" || ALWAYS_OPEN.some((p) => under(path, p))) return true;
  // Forms for adding meetings or people would only fail, since the demo can't save.
  return !path.endsWith("/new") && DEMO_PAGES.some((p) => under(path, p));
}

export const DEMO_NAV = ["/", ...DEMO_PAGES];

import { cookies } from "next/headers";
import { DEMO_COOKIE } from "@/lib/demoPaths";

// True while this browser is in the open demo (set by /demo, cleared by /demo/exit).
export async function isDemo(): Promise<boolean> {
  return (await cookies()).get(DEMO_COOKIE)?.value === "1";
}

import { NextResponse } from "next/server";
import { DEMO_COOKIE } from "@/lib/demoPaths";

// "See the demo" on /welcome: this browser sees the Columbus-area data read-only, without Lombardo's own pages.
export async function GET(request: Request) {
  const res = NextResponse.redirect(new URL("/", request.url));
  res.cookies.set(DEMO_COOKIE, "1", { path: "/", maxAge: 60 * 60 * 24 * 7, sameSite: "lax" });
  return res;
}

import { NextResponse } from "next/server";
import { DEMO_COOKIE } from "@/lib/demoPaths";

export async function GET(request: Request) {
  const res = NextResponse.redirect(new URL("/welcome", request.url));
  res.cookies.delete(DEMO_COOKIE);
  return res;
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { DEMO_COOKIE, demoAllows } from "@/lib/demoPaths";

// Refreshes the Supabase session cookie. The site is open: no login required.
export async function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname;
  // The open demo is read-only and skips Lombardo's own pages. Saving goes through server actions, so refuse those
  // (except the sign-up form).
  if (request.cookies.get(DEMO_COOKIE)?.value === "1") {
    if (request.method === "POST" && request.headers.has("next-action") && path !== "/signup") {
      return new NextResponse("The demo is read-only.", { status: 403 });
    }
    if (!demoAllows(path)) return NextResponse.redirect(new URL("/", request.url));
  }

  // The layout picks the Lombardo or public header from the path.
  const next = () => {
    const headers = new Headers(request.headers);
    headers.set("x-pathname", path);
    return NextResponse.next({ request: { headers } });
  };
  let response = next();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll: (list) => {
          list.forEach(({ name, value }) => request.cookies.set(name, value));
          response = next();
          list.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
        },
      },
    },
  );
  await supabase.auth.getUser();
  // Remember the calendar view (list / month / week) someone last picked.
  const view = request.nextUrl.searchParams.get("view");
  if (path === "/" && view && ["list", "month", "week"].includes(view)) {
    response.cookies.set("cal_view", view, { path: "/", maxAge: 60 * 60 * 24 * 365, sameSite: "lax" });
  }
  return response;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|.*\\.(?:png|jpg|svg|ico)$).*)"],
};

