"use server";

export type SignupState = { ok?: boolean; error?: string; name?: string; email?: string };

const FIELDS = ["name", "company", "email", "phone", "state", "area", "role", "note", "website"];

// Hands the form to the signup edge function, which saves it and emails AGA. No account is made yet: that comes with
// sign-in by email or text code.
export async function signUp(_: SignupState, fd: FormData): Promise<SignupState> {
  const body = Object.fromEntries(FIELDS.map((k) => [k, String(fd.get(k) ?? "").trim()]));
  const res = await fetch(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/signup`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY! },
    body: JSON.stringify(body),
  }).catch(() => null);
  const out = res ? await res.json().catch(() => ({})) : {};
  if (!res?.ok || !out.ok) return { error: out.error ?? "That didn't go through. Try again in a minute." };
  return { ok: true, name: body.name.split(" ")[0], email: body.email };
}

"use client";

import { useActionState } from "react";
import { signUp, type SignupState } from "./actions";

export default function SignupForm() {
  const [state, action, pending] = useActionState<SignupState, FormData>(signUp, {});

  if (state.ok) {
    return (
      <div className="card signup-done">
        <h2>Thanks, {state.name}.</h2>
        <p>We&apos;ll set up your account and send a sign-in code to <strong>{state.email}</strong>. There&apos;s no password.</p>
        <p>In the meantime, <a href="/demo">look around the demo</a>.</p>
      </div>
    );
  }

  return (
    <form action={action} className="card signup-form">
      <label>Your name<input name="name" required autoComplete="name" /></label>
      <label>Company<input name="company" required autoComplete="organization" /></label>
      <label>Work email<input name="email" type="email" required autoComplete="email" /></label>
      <label>Mobile phone <span className="muted">(optional, to get sign-in codes by text)</span>
        <input name="phone" type="tel" autoComplete="tel" />
      </label>
      <label>State
        <select name="state" defaultValue="OH">
          <option value="OH">Ohio</option>
          <option value="MO">Missouri</option>
          <option value="other">Somewhere else</option>
        </select>
      </label>
      <label>Cities, townships or counties you work in
        <textarea name="area" rows={2} placeholder="e.g. Dublin, Jerome Township, Delaware County" />
      </label>
      <label>What you do
        <select name="role" defaultValue="">
          <option value="">Choose one</option>
          <option>Homebuilder</option>
          <option>Developer</option>
          <option>Land broker</option>
          <option>Attorney or consultant</option>
          <option>Engineer or planner</option>
          <option>Other</option>
        </select>
      </label>
      <label>Anything else? <span className="muted">(optional)</span><textarea name="note" rows={3} /></label>
      {/* Left empty by people; filled in by spam bots. */}
      <input name="website" tabIndex={-1} autoComplete="off" className="hp" aria-hidden="true" />
      {state.error && <p className="error">{state.error}</p>}
      <button type="submit" disabled={pending}>{pending ? "Sending…" : "Sign up"}</button>
    </form>
  );
}

import type { Metadata } from "next";
import { PRODUCT } from "@/lib/demoPaths";
import SignupForm from "./SignupForm";

export const metadata: Metadata = { title: `Sign up · ${PRODUCT}` };

export default function Signup() {
  return (
    <div className="signup">
      <h1>Sign up</h1>
      <p className="muted">
        Tell us who you are and where you work. We&apos;ll set up your account for those cities and send you a sign-in
        code by email or text. No password, no card.
      </p>
      <SignupForm />
    </div>
  );
}

// Public sign-up form (web/src/app/signup): saves the request to public.signups and emails AGA about it.
// No account is created yet; that comes with sign-in by email or text code.
// Deployed with verify_jwt off (the form is public). Secrets: RESEND_API_KEY, DIGEST_FROM (shared with weekly-digest).
// The notice goes to app_settings 'signup_notify_to' (comma-separated); without it, sign-ups are only saved.
import { createClient } from "jsr:@supabase/supabase-js@2";

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
const clean = (v: unknown, max = 200) => String(v ?? "").trim().slice(0, max);
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

Deno.serve(async (req) => {
  if (req.method !== "POST") return new Response("Not found", { status: 404 });
  const b = await req.json().catch(() => ({}));
  // Honeypot: people leave it empty, bots fill it. Pretend it worked.
  if (clean(b.website)) return json({ ok: true });

  const row = {
    name: clean(b.name), company: clean(b.company), email: clean(b.email).toLowerCase(),
    phone: clean(b.phone, 40) || null, state: clean(b.state, 20) || null, area: clean(b.area, 500) || null,
    role: clean(b.role, 60) || null, note: clean(b.note, 2000) || null,
  };
  if (!row.name || !row.company || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row.email)) {
    return json({ ok: false, error: "Name, company and a valid email are needed." }, 400);
  }

  const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  // A repeat from the same email within a day is taken as the same request.
  const { data: recent } = await db.from("signups").select("id").eq("email", row.email)
    .gte("created_at", new Date(Date.now() - 864e5).toISOString()).limit(1);
  if (recent?.length) return json({ ok: true });
  const { data: saved, error } = await db.from("signups").insert(row).select("id").single();
  if (error) return json({ ok: false, error: "That didn't save. Try again in a minute." }, 500);

  const { data: setting } = await db.from("app_settings").select("value").eq("key", "signup_notify_to").maybeSingle();
  const to = String(setting?.value ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  const key = Deno.env.get("RESEND_API_KEY");
  const from = Deno.env.get("DIGEST_FROM");
  if (to.length && key && from) {
    const lines: [string, string | null][] = [
      ["Name", row.name], ["Company", row.company], ["Email", row.email], ["Phone", row.phone],
      ["State", row.state], ["Works in", row.area], ["Role", row.role], ["Note", row.note],
    ];
    const html = `<p>New sign-up on the public site:</p><table cellpadding="4">${
      lines.filter(([, v]) => v).map(([k, v]) => `<tr><td><b>${k}</b></td><td>${esc(v!)}</td></tr>`).join("")
    }</table>`;
    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from, to, reply_to: row.email, subject: `New sign-up: ${row.name}, ${row.company}`, html }),
    });
    if (res.ok) await db.from("signups").update({ notified_at: new Date().toISOString() }).eq("id", saved.id);
  }
  return json({ ok: true });
});

