import { unstable_cache } from "next/cache";

// Free Sentinel-2 satellite images of a site (10 m per pixel, a pass every few days) from Microsoft Planetary Computer,
// which needs no account. Each pass's scene classification (SCL band) is checked over the site itself, so a pass that's
// clear overall but cloudy over the site is skipped. Picks the latest clear image plus ones from about 3 and 12
// months earlier, to show change. If the free service stops, swap this file for a paid source (Planet, Nearmap).
const STAC = "https://planetarycomputer.microsoft.com/api/stac/v1/search";
const DATA = "https://planetarycomputer.microsoft.com/api/data/v1/item";
const COLLECTION = "sentinel-2-l2a";

export type Shot = { label: string; date: string; green: number; url: string };

// SCL classes: 4 vegetation, 5 bare ground or built, 6 water; 0-3 and 7-10 are no data, shadow or cloud.
const CLEAR = [4, 5, 6, 11];

type Item = { id: string; date: string; cloud: number };

// Square box `half` meters each side of the point, as [west, south, east, north].
function box(lat: number, lng: number, half: number) {
  const dLat = half / 111_320;
  const dLng = dLat / Math.cos((lat * Math.PI) / 180);
  return [lng - dLng, lat - dLat, lng + dLng, lat + dLat].map((v) => +v.toFixed(5));
}

async function search(lat: number, lng: number): Promise<Item[]> {
  const to = new Date();
  const from = new Date(to.getTime() - 400 * 864e5);
  const res = await fetch(STAC, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      collections: [COLLECTION],
      intersects: { type: "Point", coordinates: [lng, lat] },
      datetime: `${from.toISOString()}/${to.toISOString()}`,
      query: { "eo:cloud_cover": { lt: 60 } },
      sortby: [{ field: "datetime", direction: "desc" }],
      limit: 200,
      fields: { include: ["id", "properties.datetime", "properties.eo:cloud_cover"], exclude: ["assets", "links", "geometry"] },
    }),
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`Imagery search failed (${res.status})`);
  const { features } = await res.json();
  // A site on the edge of two tiles comes back twice per pass; keep the less cloudy one.
  const byDate = new Map<string, Item>();
  for (const f of features as { id: string; properties: Record<string, string | number> }[]) {
    const it = { id: f.id, date: String(f.properties.datetime).slice(0, 10), cloud: Number(f.properties["eo:cloud_cover"]) };
    const had = byDate.get(it.date);
    if (!had || it.cloud < had.cloud) byDate.set(it.date, it);
  }
  return [...byDate.values()];
}

// Share of the site that's clear, and of that, the share that's vegetation.
async function siteCover(item: Item, lat: number, lng: number) {
  const [w, s, e, n] = box(lat, lng, 250);
  const feature = { type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [[[w, s], [e, s], [e, n], [w, n], [w, s]]] } };
  const res = await fetch(`${DATA}/statistics?collection=${COLLECTION}&item=${item.id}&assets=SCL&categorical=true`, {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(feature), cache: "no-store",
  });
  if (!res.ok) return null;
  const stats = (await res.json()).properties?.statistics?.SCL_b1;
  if (!stats?.histogram) return null;
  const [counts, classes] = stats.histogram as [number[], number[]];
  const count = (pick: (c: number) => boolean) => classes.reduce((sum, c, i) => sum + (pick(c) ? counts[i] : 0), 0);
  const total = count(() => true);
  const clear = count((c) => CLEAR.includes(c));
  return total ? { clear: clear / total, green: clear ? count((c) => c === 4) / clear : 0 } : null;
}

// First clear pass among `items` (in order), checking four at a time.
async function firstClear(items: Item[], lat: number, lng: number) {
  for (let i = 0; i < Math.min(items.length, 16); i += 4) {
    const batch = items.slice(i, i + 4);
    const covers = await Promise.all(batch.map((it) => siteCover(it, lat, lng).catch(() => null)));
    const k = covers.findIndex((c) => c && c.clear >= 0.97);
    if (k >= 0) return { item: batch[k], green: covers[k]!.green };
  }
  return null;
}

const imageUrl = (id: string, lat: number, lng: number) =>
  `${DATA}/bbox/${box(lat, lng, 800).join(",")}.png?collection=${COLLECTION}&item=${id}&assets=visual&width=480&height=480&resampling=bilinear`;

async function findShots(lat: number, lng: number): Promise<Shot[]> {
  const items = await search(lat, lng);
  const latest = await firstClear(items, lat, lng);
  if (!latest) return [];
  const shots: Shot[] = [{ label: "Latest", date: latest.item.date, green: latest.green, url: imageUrl(latest.item.id, lat, lng) }];
  // Earlier passes nearest each target date (within 45 days of it).
  const day = (d: string) => new Date(d + "T00:00:00Z").getTime() / 864e5;
  for (const [label, back] of [["3 months earlier", 91], ["A year earlier", 365]] as const) {
    const target = day(latest.item.date) - back;
    const near = items.filter((it) => Math.abs(day(it.date) - target) <= 45)
      .sort((a, b) => Math.abs(day(a.date) - target) - Math.abs(day(b.date) - target));
    const hit = await firstClear(near, lat, lng);
    if (hit) shots.push({ label, date: hit.item.date, green: hit.green, url: imageUrl(hit.item.id, lat, lng) });
  }
  return shots;
}

// Cached for six hours per site (rounded to about 10 m) so page loads don't repeat the search.
export const siteShots = (lat: number, lng: number) =>
  unstable_cache(() => findShots(lat, lng), ["satellite", lat.toFixed(4), lng.toFixed(4)], { revalidate: 6 * 3600 })();

export const exploreUrl = (lat: number, lng: number) =>
  `https://browser.dataspace.copernicus.eu/?zoom=15&lat=${lat.toFixed(5)}&lng=${lng.toFixed(5)}`;

import { exploreUrl, siteShots } from "@/lib/satellite";
import { fmtDate } from "@/lib/format";

// Recent free satellite images of a site, latest first, with earlier ones to compare (feature "satellite").
// Wrap in <Suspense>: finding clear passes can take a few seconds the first time for a site.
export default async function SatelliteCard({ lat, lng }: { lat: number; lng: number }) {
  const shots = await siteShots(lat, lng).catch(() => null);
  return (
    <div className="card">
      {shots === null ? (
        <p className="muted small" style={{ margin: 0 }}>The satellite image service didn&apos;t answer. Try again later.</p>
      ) : shots.length === 0 ? (
        <p className="muted small" style={{ margin: 0 }}>No clear pass over this site recently (clouds every time).</p>
      ) : (
        <div className="sat-grid">
          {shots.map((s) => (
            <figure key={s.date}>
              <a href={s.url} target="_blank" rel="noreferrer" className="sat-img">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={s.url} alt={`Satellite image of the site, ${fmtDate(s.date)}`} width={480} height={480} loading="lazy" />
                <span className="sat-pin" aria-hidden="true" />
              </a>
              <figcaption>
                <strong>{s.label}</strong> · {fmtDate(s.date)}
                <span className="muted small"> · {Math.round(s.green * 100)}% green</span>
              </figcaption>
            </figure>
          ))}
        </div>
      )}
      <p className="source">
        Sentinel-2 (European Space Agency) via Microsoft Planetary Computer: free, 10 m per pixel, a pass every few days,
        cloudy passes skipped. Each image is about a mile across with the site at the center. &quot;Green&quot; is the
        share of the ground within about 250 m that reads as vegetation; a big drop usually means clearing or grading,
        but fields also go brown after harvest, so compare against a year earlier.{" "}
        <a href={exploreUrl(lat, lng)} target="_blank" rel="noreferrer">Explore every date ↗</a>
      </p>
    </div>
  );
}

