// OYL (On Your Lot) lots, from Chad's "OYL Tracker" spreadsheet (/oyl). Each lot is a project; the project holds the
// address, municipality, diligence end and Lombardo's purchase date, oyl_lots the rest.
export const LOT_TYPES = ["Walkout", "In-Grade", "Lookout", "TBD"];
export const OWNERSHIP = ["Pending", "Lombardo", "Customer", "In Diligence"];
export const SALES_STATUS = ["Reserved", "Flashed", "Customer Purchased"];

export const MONEY_FIELDS = ["acquisition_price", "municipality_cost", "arb_cost", "site_cost", "contract_price", "jpp_projection", "final_sale_price"] as const;
export const TEXT_FIELDS = ["lot_type", "ownership", "sales_status", "civil_engineer", "sign_status", "hoa_contact", "hoa_phone", "largest_home"] as const;
export const DATE_FIELDS = ["flashed_on", "customer_purchased_on"] as const;

export type Lot = {
  id: number;
  project_id: number;
  lot_type: string | null;
  ownership: string | null;
  sales_status: string | null;
  flashed_on: string | null;
  customer_purchased_on: string | null;
  acquisition_price: number | null;
  municipality_cost: number | null;
  arb_cost: number | null;
  site_cost: number | null;
  civil_engineer: string | null;
  contract_price: number | null;
  jpp_projection: number | null;
  final_sale_price: number | null;
  sign_status: string | null;
  hoa_contact: string | null;
  hoa_phone: string | null;
  largest_home: string | null;
  projects: {
    id: number; name: string; address: string | null; jurisdiction_id: string | null; stage: string;
    diligence_expires_on: string | null; closing_on: string | null; jurisdictions: { name: string } | null;
  };
};

export const LOT_SELECT = "*, projects!inner(id, name, address, jurisdiction_id, stage, diligence_expires_on, closing_on, jurisdictions(name))";

// The sheet's Total: acquisition + municipality + ARB + site cost.
export const lotTotal = (l: Lot) =>
  (l.acquisition_price ?? 0) + (l.municipality_cost ?? 0) + (l.arb_cost ?? 0) + (l.site_cost ?? 0);

const dayNum = (d: string) => new Date(d + "T00:00:00Z").getTime() / 864e5;
// Days from Lombardo's purchase to a later date (the sheet's "Days until Flashed" / "Days until Customer Purchase").
export const daysAfterPurchase = (l: Lot, d: string | null) =>
  d && l.projects.closing_on ? Math.round(dayNum(d) - dayNum(l.projects.closing_on)) : null;

export const isClosed = (l: Lot) => l.ownership === "Customer" || l.sales_status === "Customer Purchased";

export const money = (n: number | null) =>
  n == null ? "" : n.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

// "$412,500" / "412500" / "none" → number or null.
export function parseMoney(v: FormDataEntryValue | null) {
  const s = String(v ?? "").replace(/[$,\s]/g, "");
  return s && !Number.isNaN(Number(s)) ? Number(s) : null;
}

// The sheet's lot-count box, with each line's purchase dollars.
export function lotSummary(lots: Lot[]) {
  const line = (label: string, pick: (l: Lot) => boolean) => {
    const ls = lots.filter(pick);
    return { label, count: ls.length, dollars: ls.reduce((s, l) => s + (l.acquisition_price ?? 0), 0) };
  };
  const hasBuyer = (l: Lot) => l.sales_status === "Flashed" || l.sales_status === "Reserved";
  return [
    line("Lombardo owns", (l) => l.ownership === "Lombardo"),
    line("Owned, customer has flashed or reserved", (l) => l.ownership === "Lombardo" && hasBuyer(l)),
    line("Owned, no buyer yet", (l) => l.ownership === "Lombardo" && !hasBuyer(l)),
    line("Under contract to purchase (pending or in diligence)", (l) => l.ownership === "Pending" || l.ownership === "In Diligence"),
  ];
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { geocode, placeName } from "@/lib/geocode";
import { DATE_FIELDS, MONEY_FIELDS, TEXT_FIELDS, parseMoney } from "@/lib/oyl";

const text = (fd: FormData, key: string) => String(fd.get(key) ?? "").trim() || null;

function lotFromForm(fd: FormData) {
  const row: Record<string, string | number | null> = { updated_at: new Date().toISOString() };
  for (const k of TEXT_FIELDS) row[k] = text(fd, k);
  for (const k of DATE_FIELDS) row[k] = text(fd, k);
  for (const k of MONEY_FIELDS) row[k] = parseMoney(fd.get(k));
  return row;
}

// The project side: address and municipality (re-located on change), diligence end and purchase date. A lot the
// customer has bought moves the project to Closed; a closed one that's reopened goes back to OYL.
function projectFromForm(fd: FormData) {
  const address = text(fd, "address");
  const customer = text(fd, "ownership") === "Customer" || text(fd, "sales_status") === "Customer Purchased";
  return {
    name: text(fd, "name") ?? address,
    address,
    jurisdiction_id: text(fd, "jurisdiction_id"),
    diligence_expires_on: text(fd, "diligence_expires_on"),
    closing_on: text(fd, "closing_on"),
    customer,
  };
}

async function locate(projectId: number) {
  const supabase = await createClient();
  const { data: p } = await supabase.from("projects").select("address, jurisdictions(name)").eq("id", projectId).single();
  const jname = (p?.jurisdictions as unknown as { name: string } | null)?.name ?? "";
  const point = p?.address ? await geocode(p.address, placeName(jname)) : null;
  await supabase.from("projects").update({ lat: point?.lat ?? null, lng: point?.lng ?? null }).eq("id", projectId);
}

export async function createLot(fd: FormData) {
  const { customer, ...project } = projectFromForm(fd);
  if (!project.address) return;
  const supabase = await createClient();
  const { data: p, error } = await supabase.from("projects").insert({ ...project, stage: customer ? "closed" : "oyl" }).select("id").single();
  if (error) throw new Error(error.message);
  const { error: lotError } = await supabase.from("oyl_lots").insert({ ...lotFromForm(fd), project_id: p.id });
  if (lotError) throw new Error(lotError.message);
  if (project.jurisdiction_id) await supabase.from("jurisdictions").update({ followed: true }).eq("id", project.jurisdiction_id).eq("followed", false);
  await locate(p.id);
  revalidatePath("/", "layout");
  redirect("/oyl");
}

export async function updateLot(lotId: number, fd: FormData) {
  const supabase = await createClient();
  const { data: lot } = await supabase.from("oyl_lots").select("project_id, projects(address, jurisdiction_id, stage)").eq("id", lotId).single();
  if (!lot) return;
  const before = lot.projects as unknown as { address: string | null; jurisdiction_id: string | null; stage: string };
  const { customer, ...project } = projectFromForm(fd);
  const stage = customer ? "closed" : before.stage === "closed" ? "oyl" : before.stage;
  const { error } = await supabase.from("projects").update({ ...project, stage }).eq("id", lot.project_id);
  if (error) throw new Error(error.message);
  const { error: lotError } = await supabase.from("oyl_lots").update(lotFromForm(fd)).eq("id", lotId);
  if (lotError) throw new Error(lotError.message);
  if (project.address !== before.address || project.jurisdiction_id !== before.jurisdiction_id) await locate(lot.project_id);
  revalidatePath("/", "layout");
  redirect("/oyl");
}

import { LOT_TYPES, OWNERSHIP, SALES_STATUS, type Lot } from "@/lib/oyl";

// Add / edit form for an OYL lot: the columns of Chad's sheet, grouped.
export default function LotForm({ action, lot, jurisdictions, submitLabel }: {
  action: (fd: FormData) => Promise<void>;
  lot?: Lot;
  jurisdictions: { id: string; name: string }[];
  submitLabel: string;
}) {
  const p = lot?.projects;
  const pick = (name: string, label: string, options: string[], value: string | null | undefined) => (
    <label>{label}
      <select name={name} defaultValue={value ?? ""}>
        <option value="">—</option>
        {options.map((o) => <option key={o}>{o}</option>)}
      </select>
    </label>
  );
  const date = (name: string, label: string, value: string | null | undefined) => (
    <label>{label}<input type="date" name={name} defaultValue={value ?? ""} /></label>
  );
  const field = (name: string, label: string, value: string | number | null | undefined) => (
    <label>{label}<input name={name} defaultValue={value ?? ""} /></label>
  );
  const dollars = (name: string, label: string, value: number | null | undefined) => (
    <label>{label}<input name={name} inputMode="decimal" placeholder="$" defaultValue={value ?? ""} /></label>
  );

  return (
    <form action={action} className="card stack-form oyl-form">
      <fieldset>
        <legend>Lot</legend>
        <label>Property address<input name="address" required defaultValue={p?.address ?? ""} /></label>
        <label>Municipality
          <select name="jurisdiction_id" defaultValue={p?.jurisdiction_id ?? ""}>
            <option value="">—</option>
            {jurisdictions.map((j) => <option key={j.id} value={j.id}>{j.name}</option>)}
          </select>
        </label>
        {pick("lot_type", "Lot type", LOT_TYPES, lot?.lot_type)}
        {field("largest_home", "Largest home available", lot?.largest_home)}
      </fieldset>
      <fieldset>
        <legend>Dates and status</legend>
        {date("diligence_expires_on", "Diligence ends", p?.diligence_expires_on)}
        {date("closing_on", "Lombardo purchase date", p?.closing_on)}
        {pick("ownership", "Ownership", OWNERSHIP, lot?.ownership)}
        {pick("sales_status", "Sales status", SALES_STATUS, lot?.sales_status)}
        {date("flashed_on", "Flashed sale date", lot?.flashed_on)}
        {date("customer_purchased_on", "Customer purchased lot", lot?.customer_purchased_on)}
      </fieldset>
      <fieldset>
        <legend>Costs and prices</legend>
        {dollars("acquisition_price", "Acquisition price", lot?.acquisition_price)}
        {dollars("municipality_cost", "Municipality", lot?.municipality_cost)}
        {dollars("arb_cost", "ARB", lot?.arb_cost)}
        {dollars("site_cost", "Site cost (Doug/Travis)", lot?.site_cost)}
        {dollars("contract_price", "Contract price", lot?.contract_price)}
        {dollars("jpp_projection", "JPP projection", lot?.jpp_projection)}
        {dollars("final_sale_price", "Final sales price", lot?.final_sale_price)}
        {field("civil_engineer", "Civil engineer", lot?.civil_engineer)}
      </fieldset>
      <fieldset>
        <legend>Sign and HOA</legend>
        {field("sign_status", "Sign status", lot?.sign_status)}
        {field("hoa_contact", "HOA contact", lot?.hoa_contact)}
        {field("hoa_phone", "HOA phone", lot?.hoa_phone)}
      </fieldset>
      <div><button type="submit">{submitLabel}</button></div>
    </form>
  );
}

