// Team list for /team: list, add and remove the people who can sign in. Called by the web app's server actions with the
// signed-in user's access token; only someone already on the team (public.team_members) may use it. Adding creates the
// Supabase Auth user (email and/or mobile, both pre-confirmed so a one-time code works right away) and the team row.
// Deployed with verify_jwt off; the token is checked here instead.
import { createClient } from "jsr:@supabase/supabase-js@2";

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });

// "(314) 555-0100" → "+13145550100"
function e164(input: string) {
  const digits = input.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  return input.trim().startsWith("+") && digits.length > 10 ? `+${digits}` : null;
}

Deno.serve(async (req) => {
  if (req.method !== "POST") return new Response("Not found", { status: 404 });
  const admin = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  const jwt = (req.headers.get("Authorization") ?? "").replace(/^Bearer\s+/i, "");
  const { data: { user: me } } = await admin.auth.getUser(jwt);
  if (!me) return json({ error: "Sign in first." }, 401);
  const { data: mine } = await admin.from("team_members").select("company").eq("user_id", me.id).maybeSingle();
  if (!mine) return json({ error: "You're not on the team list." }, 403);

  const b = await req.json().catch(() => ({}));

  if (b.action === "list") {
    const [{ data: rows }, { data: users, error }] = await Promise.all([
      admin.from("team_members").select("user_id, added_at").eq("company", mine.company),
      admin.auth.admin.listUsers({ perPage: 1000 }),
    ]);
    if (error) return json({ error: error.message }, 500);
    const byId = new Map(users.users.map((u) => [u.id, u]));
    return json({
      me: me.id,
      members: (rows ?? []).map((r) => {
        const u = byId.get(r.user_id);
        return { id: r.user_id, email: u?.email ?? null, phone: u?.phone ? `+${u.phone.replace(/^\+/, "")}` : null,
          added_at: r.added_at, last_sign_in_at: u?.last_sign_in_at ?? null };
      }),
    });
  }

  if (b.action === "add") {
    const email = String(b.email ?? "").trim().toLowerCase() || null;
    const phoneIn = String(b.phone ?? "").trim();
    const phone = phoneIn ? e164(phoneIn) : null;
    if (phoneIn && !phone) return json({ error: "Enter the mobile number as 10 digits, e.g. 314-555-0100." }, 400);
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({ error: "That email doesn't look right." }, 400);
    if (!email && !phone) return json({ error: "Enter an email, a mobile number, or both." }, 400);

    // Someone who already has an account (matched by email) gets the phone added and joins the team.
    const { data: list } = await admin.auth.admin.listUsers({ perPage: 1000 });
    const existing = email ? list?.users.find((u) => u.email?.toLowerCase() === email) : null;
    let userId: string;
    if (existing) {
      if (phone) {
        const { error } = await admin.auth.admin.updateUserById(existing.id, { phone, phone_confirm: true });
        if (error) return json({ error: error.message }, 400);
      }
      userId = existing.id;
    } else {
      const { data, error } = await admin.auth.admin.createUser({
        ...(email ? { email, email_confirm: true } : {}),
        ...(phone ? { phone, phone_confirm: true } : {}),
      });
      if (error) return json({ error: /already/i.test(error.message) ? "That email or number already has an account." : error.message }, 400);
      userId = data.user.id;
    }
    const { error } = await admin.from("team_members").upsert({ user_id: userId, company: mine.company });
    if (error) return json({ error: error.message }, 500);
    return json({ ok: true });
  }

  if (b.action === "remove") {
    const id = String(b.id ?? "");
    if (id === me.id) return json({ error: "You can't remove yourself." }, 400);
    // Off the team list only; the login itself stays (it can't see anything without the team row).
    const { error } = await admin.from("team_members").delete().eq("user_id", id).eq("company", mine.company);
    if (error) return json({ error: error.message }, 500);
    return json({ ok: true });
  }

  return json({ error: "Unknown action." }, 400);
});

"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";

export type Member = { id: string; email: string | null; phone: string | null; added_at: string; last_sign_in_at: string | null };

// Calls the `team` edge function as the signed-in user (it checks they're on the team).
export async function team<T>(body: Record<string, string>): Promise<T & { error?: string }> {
  const supabase = await createClient();
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) return { error: "Sign in first." } as T & { error?: string };
  const res = await fetch(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/team`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
      Authorization: `Bearer ${session.access_token}`,
    },
    body: JSON.stringify(body),
    cache: "no-store",
  }).catch(() => null);
  if (!res) return { error: "The team service didn't answer. Try again." } as T & { error?: string };
  return res.json().catch(() => ({ error: `Team service error (${res.status}).` }));
}

export type AddState = { ok?: boolean; error?: string };

export async function addMember(_: AddState, fd: FormData): Promise<AddState> {
  const out = await team<{ ok?: boolean }>({ action: "add", email: String(fd.get("email") ?? ""), phone: String(fd.get("phone") ?? "") });
  if (out.error) return { error: out.error };
  revalidatePath("/team");
  return { ok: true };
}

export async function removeMember(id: string) {
  const out = await team<{ ok?: boolean }>({ action: "remove", id });
  if (out.error) throw new Error(out.error);
  revalidatePath("/team");
}

"use client";

import { useActionState } from "react";
import { addMember, type AddState } from "./actions";

export default function AddMember() {
  const [state, action, pending] = useActionState<AddState, FormData>(addMember, {});
  return (
    <form action={action} className="inline-form">
      <label className="grow">Work email<input name="email" type="email" placeholder="name@company.com" /></label>
      <label>Mobile (optional)<input name="phone" type="tel" placeholder="314-555-0100" /></label>
      <button type="submit" disabled={pending}>{pending ? "Adding…" : "Add"}</button>
      {state.error && <p className="error" style={{ flexBasis: "100%", margin: 0 }}>{state.error}</p>}
      {state.ok && <p className="small" style={{ flexBasis: "100%", margin: 0 }}>Added. They can sign in at /login with a code.</p>}
    </form>
  );
}

import Link from "next/link";
import { faUsers } from "@fortawesome/free-solid-svg-icons";
import PageTitle from "@/components/PageTitle";
import { fmtDate } from "@/lib/format";
import { team, removeMember, type Member } from "./actions";
import AddMember from "./AddMember";

export const dynamic = "force-dynamic";

// Who can sign in. Anyone on the team can add or remove people (one team, Lombardo, for now).
export default async function TeamPage() {
  const out = await team<{ me: string; members: Member[] }>({ action: "list" });
  if (out.error) {
    return (
      <>
        <PageTitle href="/team" icon={faUsers}>Team</PageTitle>
        <p>{out.error}{out.error.startsWith("Sign in") && <> <Link href="/login?next=/team">Sign in</Link></>}</p>
      </>
    );
  }
  const members = [...out.members].sort((a, b) => (a.email ?? a.phone ?? "").localeCompare(b.email ?? b.phone ?? ""));
  return (
    <>
      <PageTitle href="/team" icon={faUsers}>Team</PageTitle>
      <p className="muted">
        People who can sign in. They sign in at <code>/login</code> with a 6-digit code sent to their email, or by text if
        a mobile number is on file. No passwords.
      </p>
      <div className="table-wrap">
        <table>
          <thead><tr><th>Email</th><th>Mobile</th><th>Last signed in</th><th></th></tr></thead>
          <tbody>
            {members.map((m) => (
              <tr key={m.id}>
                <td>{m.email ?? <span className="muted">—</span>}{m.id === out.me && <span className="muted small"> (you)</span>}</td>
                <td>{m.phone ?? <span className="muted">—</span>}</td>
                <td>{m.last_sign_in_at ? fmtDate(m.last_sign_in_at.slice(0, 10)) : <span className="muted">Never</span>}</td>
                <td>
                  {m.id !== out.me && (
                    <form action={removeMember.bind(null, m.id)}>
                      <button type="submit" className="link danger">Remove</button>
                    </form>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <h2>Add someone</h2>
      <div className="card">
        <AddMember />
        <p className="source">Adding a mobile number to someone already listed: enter their email and the number.</p>
      </div>
    </>
  );
}

